import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.CWgsre3x.js";const _=JSON.parse('{"title":"Ασφαλής επανάληψη δημιουργίας κράτησης","description":"","frontmatter":{},"headers":[],"relativePath":"el/developers/idempotency.md","filePath":"el/developers/idempotency.md"}'),r={name:"el/developers/idempotency.md"};function i(l,e,c,p,n,s){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="ασφαλης-επαναληψη-δημιουργιας-κρατησης" tabindex="-1">Ασφαλής επανάληψη δημιουργίας κράτησης <a class="header-anchor" href="#ασφαλης-επαναληψη-δημιουργιας-κρατησης" aria-label="Permalink to &quot;Ασφαλής επανάληψη δημιουργίας κράτησης&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Προσχέδιο βάσει πηγαίου κώδικα · v0.7.9. Επιβεβαιώστε διαθεσιμότητα και δικαιώματα στην εγκεκριμένη έκδοση.</p></div><h2 id="κλειδι-idempotency" tabindex="-1">Κλειδί idempotency <a class="header-anchor" href="#κλειδι-idempotency" aria-label="Permalink to &quot;Κλειδί idempotency&quot;">​</a></h2><p>Για <code>POST /api/v1/reservations</code>, αποστείλετε <code>Idempotency-Key</code> με 8–128 χαρακτήρες: γράμματα, ψηφία, τελεία, κάτω παύλα, άνω-κάτω τελεία ή παύλα. Δημιουργήστε μοναδικό κλειδί ανά πρόθεση κράτησης.</p><ol><li>Διατηρήστε το κλειδί και το αμετάβλητο αίτημα αν η απόκριση δικτύου είναι αβέβαιη.</li><li>Επαναλάβετε την ίδια πρόθεση με το ίδιο κλειδί και περιεχόμενο. Μη δημιουργείτε νέα πρόθεση επειδή χάθηκε η απόκριση.</li><li>Αν αλλάζει σκόπιμα το αίτημα, χρησιμοποιήστε νέο κλειδί μόνο αφού διαπιστώσετε αν υπάρχει ήδη η προηγούμενη κράτηση.</li><li>Καταγράψτε τον κωδικό κράτησης που επιστράφηκε στη διαδικασία της εφαρμογής πελάτη.</li></ol><table tabindex="0"><thead><tr><th>Απόκριση</th><th>Ερμηνεία</th></tr></thead><tbody><tr><td>201</td><td>Νέα κράτηση ή επανάληψη αποτελέσματος</td></tr><tr><td>201 + <code>X-Idempotency-Replayed: true</code></td><td>Επιστροφή υπάρχοντος αποτελέσματος</td></tr><tr><td>400</td><td>Απουσία ή μη έγκυρο κλειδί ή κράτηση</td></tr><tr><td>409</td><td>Ίδιο κλειδί με διαφορετικό περιεχόμενο ή άλλη σύγκρουση</td></tr><tr><td>503</td><td>Μη διαθέσιμο απαιτούμενο σχήμα idempotency</td></tr></tbody></table><p>Το 503 με <code>RESERVATION_IDEMPOTENCY_MIGRATION_REQUIRED</code> δεν πρέπει να οδηγεί σε απροστάτευτη δημιουργία. Επιλύστε τη ρύθμιση έκδοσης με διαχειριστή. Το κλειδί περιορίζεται στην εταιρεία και δεν αποτελεί ταυτοποίηση.</p><p>Δείτε <a href="/el/developers/reservation-api.html">API κρατήσεων</a>.</p>',8)])])}const h=t(r,[["render",i]]);export{_ as __pageData,h as default};
